import os from 'os';

async function toggleTracking() {
  // Turns on or off: what you do in the timeline (clicks, the replay) is added as blocks.
  const d = os.get('extension.views.timeline-view.ui-data');
  d.track_timeline = !d.track_timeline;
}

local.select.code:
import os from 'os';
import ctx from 'ctx';

async function select({ id }) {
  // Choosing a block stops the replay and shows the block under the header (step-view).
  const d = os.get('extension.views.timeline-view.ui-data');
  d.selected = id;
  d.playing = false;
  if (!os.mounted('extension.views.step-view')) await ctx.call('extension.functions.render', { view_path: 'extension.views.step-view' });
}

local.next.code:
import os from 'os';
import ctx from 'ctx';

async function next({ delta }) {
  // Moves delta blocks. The replay stops at the block that was the last when it started.
  const d = os.get('extension.views.timeline-view.ui-data'), R = os.refs['timeline-view'], ids = R.steps;
  let at = ids.indexOf(d.selected);
  if (at < 0) at = ids.length - 1;
  const to = Math.max(0, Math.min(ids.length - 1, at + (+delta || 0)));
  d.selected = ids[to];
  if (to === ids.length - 1 || (d.playing && ids[to] === R.end)) d.playing = false;
  if (!os.mounted('extension.views.step-view')) await ctx.call('extension.functions.render', { view_path: 'extension.views.step-view' });
}

local.reload.code:
import os from 'os';

async function reload() {
  // Reloads the page, so the history starts again from the first step. The timeline opens again and replays it.
  if (os.get('extension.views.state-view.ui-data.unsaved')) throw new Error('The state has unsaved changes. Save them first.');
  try { sessionStorage.setItem('agent-os.timeline-replay', '1'); } catch (e) { location.hash = 'timeline-replay'; }
  location.reload();
}

local.play.code:
import os from 'os';
import ctx from 'ctx';

async function play() {
  // Starts or stops the replay. From the last block, it starts again at the first.
  const d = os.get('extension.views.timeline-view.ui-data'), R = os.refs['timeline-view'], ids = R.steps;
  d.playing = !d.playing;
  const at = ids.indexOf(d.selected);
  if (d.playing && (at < 0 || at === ids.length - 1)) d.selected = ids[0];
  // With the timeline tracked, each move adds a block: the replay ends at the block that is the last now.
  if (d.playing) R.end = ids[ids.length - 1];
