import os from 'os';
import ctx from 'ctx';

async function init() {
  // The view of the chosen block draws itself after every call (local.refresh), and now.
  os.refs['step-view'] = {};
  os.watch('extension.views.step-view', 'local.refresh');
  await ctx.call('local.refresh', { after: 'local.init' });
}

local.refresh.code:
import os from 'os';
import ctx from 'ctx';

async function refresh({ after }) {
  const v = 'extension.views.step-view', d = os.get(v + '.ui-data'), T = os.refs['timeline-view'];
  // The tabs are drawn again from ui-data.
  const tmp = document.createElement('div');
  tmp.innerHTML = os.template(os.get(v + '.html'), d);
  const tabs = tmp.querySelector('.tl-tabs');
  ctx.root.querySelector('.tl-tabs').replaceWith(tabs);
  os.bind(tabs, v);
  const el = (tag, cls, text) => { const x = document.createElement(tag); if (cls) x.className = cls; if (text !== undefined) x.textContent = text; return x; };
  const title = ctx.root.querySelector('#st-title'), box = ctx.root.querySelector('#tl-detail');
  // The timeline keeps the chosen block and draws what is in it.
  const cur = T && T.current;
  if (!cur) { title.textContent = ''; box.textContent = 'Choose a block in the timeline.'; return; }
  const key = cur.id + ':' + d.tab, keep = T.shown === key ? box.scrollTop : 0;
  title.textContent = '';
  title.appendChild(el('span', 'tl-kind', cur.label));
  title.appendChild(el('span', 'tl-name', cur.name));
  title.appendChild(el('span', 'tl-time', T.since(cur.ms) + (cur.took !== undefined ? ' · ' + cur.took + ' ms' : '')));
  box.textContent = '';
  // A newly chosen block shows its calls one after the other.
  box.classList.toggle('anim', T.shown !== key);
  T.shown = key;
  box.appendChild(el('p', 'tl-text', cur.text));
  if (d.tab === 'state') T.drawChanges(box);
  else {
    box.appendChild(el('div', 'tl-detail-sub', 'What happens inside this block'));
    const inside = el('div', 'tl-inside');
    T.drawDetails(inside);
    box.appendChild(inside);
  }
  box.scrollTop = keep;
}

