import os from 'os';

async function filter({ text }) {
  // local.refresh shows in the editor only the paths that have the text.
  const d = os.get('extension.views.state-view.ui-data');
  d.filter = String(text || '');
}

local.filter-kind.code:
import os from 'os';

async function filterKind({ kind }) {
  // local.refresh hides the kinds that are off: files, views or functions.
  const d = os.get('extension.views.state-view.ui-data');
  if (!(kind in d.filter_kinds)) throw new Error('No kind ' + kind);
  d.filter_kinds[kind] = !d.filter_kinds[kind];
}

